// test_climate.mjs -- verifies public/js/climate.js's Weibull-based
// exceedance / NEN 8100 / Lawson LDDC port against
// E:\PINN\v2\climate\windclimate.py (method='weibull' path only -- see
// web/build/build_climate_assets.py for why the empirical/'auto' path
// isn't ported) on a few K vectors (fixtures/climate_vectors.json,
// generated by gen_reference.py).
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import {
  annualExceedanceWeibull, nen8100ComfortClass, nen8100DangerClass,
  gustEquivalentMean, uHOverU10, NEN8100_COMFORT_THRESHOLD_MS, NEN8100_DANGER_THRESHOLD_MS,
  LAWSON_LDDC_COMFORT_THRESHOLDS_MS, LAWSON_LDDC_DANGER_THRESHOLDS_MS,
} from "../public/js/climate.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const TOL = 1e-9;

function loadSectors() {
  const csv = readFileSync(join(__dirname, "../../climate/windrose_16.csv"), "utf-8").trim().split("\n");
  const header = csv[0].split(",");
  return csv.slice(1).map((line) => {
    const vals = line.split(",");
    const row = {};
    header.forEach((h, i) => { row[h] = isNaN(Number(vals[i])) ? vals[i] : Number(vals[i]); });
    return { theta_deg: row.sector_centre_deg, frequency: row.frequency, weibull_c: row.weibull_c, weibull_k: row.weibull_k };
  });
}

function checkClose(label, a, b, tol, failures) {
  const diff = Math.abs(a - b);
  if (diff >= tol) failures.push(`${label}: JS=${a} Python=${b} diff=${diff}`);
  return diff;
}

function main() {
  const sectors = loadSectors();
  const fixtures = JSON.parse(readFileSync(join(__dirname, "fixtures/climate_vectors.json"), "utf-8"));
  const failures = [];
  let maxDiff = 0;

  for (const c of fixtures.cases) {
    const res5 = annualExceedanceWeibull(sectors, c.K, NEN8100_COMFORT_THRESHOLD_MS);
    const res15 = annualExceedanceWeibull(sectors, c.K, NEN8100_DANGER_THRESHOLD_MS);
    maxDiff = Math.max(maxDiff, checkClose(`${c.name} p_gt_5`, res5.annualProbability, c.p_gt_5, TOL, failures));
    maxDiff = Math.max(maxDiff, checkClose(`${c.name} p_gt_15`, res15.annualProbability, c.p_gt_15, TOL, failures));

    const cls = nen8100ComfortClass(res5.annualProbability);
    if (cls !== c.nen8100_class) failures.push(`${c.name} nen8100_class: JS=${cls} Python=${c.nen8100_class}`);
    const dangerCls = nen8100DangerClass(res15.annualProbability);
    if (dangerCls !== c.nen8100_danger_class) failures.push(`${c.name} nen8100_danger_class: JS=${dangerCls} Python=${c.nen8100_danger_class}`);

    for (const [label, thr] of Object.entries(LAWSON_LDDC_COMFORT_THRESHOLDS_MS)) {
      const r = annualExceedanceWeibull(sectors, c.K, thr);
      const py = c.lawson.comfort[label];
      maxDiff = Math.max(maxDiff, checkClose(`${c.name} lawson.${label} p_exceed`, r.annualProbability, py.p_exceed, TOL, failures));
      if ((r.annualProbability < 0.05) !== py.passes) failures.push(`${c.name} lawson.${label} passes mismatch`);
    }
    for (const [label, thr] of Object.entries(LAWSON_LDDC_DANGER_THRESHOLDS_MS)) {
      const r = annualExceedanceWeibull(sectors, c.K, thr);
      const py = c.lawson.danger[label];
      maxDiff = Math.max(maxDiff, checkClose(`${c.name} lawson.danger.${label} p_exceed`, r.annualProbability, py.p_exceed, TOL, failures));
    }
  }

  for (const g of fixtures.gem_cases) {
    const gem = gustEquivalentMean(g.u_local, g.k_local);
    maxDiff = Math.max(maxDiff, checkClose(`GEM(${g.u_local},${g.k_local})`, gem, g.expected_gem, TOL, failures));
  }

  // transfer.py cross-check: U_H(U10)/U10 per sector (climate.js:uHOverU10)
  // against transfer.py:InflowResult.U_H / U_H_over_U10, method='macdonald',
  // real Zona Tec H_ref (fixtures/transfer_vectors.json).
  const climateData = JSON.parse(readFileSync(join(__dirname, "../public/data/climate.json"), "utf-8"));
  const transferFixtures = JSON.parse(readFileSync(join(__dirname, "fixtures/transfer_vectors.json"), "utf-8"));
  let maxTransferDiff = 0;
  for (const tc of transferFixtures.cases) {
    const sector = climateData.sectors.find((s) => s.theta_deg === tc.theta_deg);
    const jsVal = uHOverU10(sector, transferFixtures.h_ref, climateData.constants, "macdonald");
    maxTransferDiff = Math.max(maxTransferDiff, checkClose(`U_H/U10 theta=${tc.theta_deg}`, jsVal, tc.expected_u_h_over_u10, 1e-9, failures));
  }
  console.log(`  transfer.py cross-check (${transferFixtures.cases.length} sectores): max|diff| = ${maxTransferDiff.toExponential(3)}`);

  console.log(`[test_climate] ${fixtures.cases.length} vectores K, ${fixtures.gem_cases.length} casos GEM`);
  console.log(`  max|diff| en probabilidades = ${maxDiff.toExponential(3)} (tolerancia ${TOL})`);
  if (failures.length) {
    console.error("FALLO:\n" + failures.join("\n"));
    process.exit(1);
  }
  console.log("OK: climate.js reproduce windclimate.py/transfer.py (ruta Weibull) exactamente.");
}

main();
